  select x.id, x.item_kind, x.item_id, x.title_en, x.title_ar, x.nqf_level, x.notional_hours, x.credits, x.indicative, x.basis_en, x.basis_ar, x.stack_ids, x.status, x.listed, x.source_url, x.as_of, x.version, x.updated_by, x.updated_at from jsonb_populate_recordset(null::kafaa_credit_tags, $j$[{"id":"ct:microcred:mcd-mc-ai-assurer-v1","item_kind":"microcred","item_id":"mcd-mc-ai-assurer-v1","title_en":"AI assurer","title_ar":"ضامن مخرجات الذكاء الاصطناعي","nqf_level":5,"notional_hours":15,"credits":1.5,"indicative":true,"basis_en":"Evidence review and assessment component (half of the 30 learning hours); courses in the criteria count separately.","basis_ar":"مكوّن مراجعة الأدلة والتقييم (نصف ساعات التعلم البالغة 30)؛ تُحتسب الدورات الواردة في المعايير بشكل منفصل.","stack_ids":["st-ai-plant"],"status":"published","listed":true,"source_url":"https://uaelegislation.gov.ae/en/legislations/2615/download","as_of":"2026-10-10","version":1,"updated_by":"p-training-mgr","updated_at":"2026-10-10T09:00:00Z"},{"id":"ct:microcred:mcd-mc-clean-energy-v1","item_kind":"microcred","item_id":"mcd-mc-clean-energy-v1","title_en":"Clean energy systems","title_ar":"أنظمة الطاقة النظيفة","nqf_level":4,"notional_hours":10,"credits":1,"indicative":true,"basis_en":"Evidence review and assessment component (half of the 20 learning hours); courses in the criteria count separately.","basis_ar":"مكوّن مراجعة الأدلة والتقييم (نصف ساعات التعلم البالغة 20)؛ تُحتسب الدورات الواردة في المعايير بشكل منفصل.","stack_ids":["st-clean-energy"],"status":"published","listed":true,"source_url":"https://uaelegislation.gov.ae/en/legislations/2615/download","as_of":"2026-10-10","version":1,"updated_by":"p-training-mgr","updated_at":"2026-10-10T09:00:00Z"},{"id":"ct:microcred:mcd-mc-cyber-hygiene-v1","item_kind":"microcred","item_id":"mcd-mc-cyber-hygiene-v1","title_en":"Cyber hygiene for all staff","title_ar":"النظافة السيبرانية لجميع الموظفين","nqf_level":3,"notional_hours":5,"credits":0.5,"indicative":true,"b