x
  where exists (select 1 from kafaa_people p where p.id = x.person_id) and exists (select 1 from kafaa_credit_tags t where t.id = x.tag_id)
    and exists (select 1 from kafaa_microcred_awards a where a.id = x.source_id and a.status = 'awarded')
  on conflict (id) do nothing;
do $$ declare x text; begin
  for x in select distinct a.person_id from kafaa_microcred_awards a join kafaa_microcred_defs d on d.id = a.def_id
    where a.status = 'awarded' and d.code = any(array['MC-AI-ASSURER', 'MC-DATA-DECISIONS', 'MC-TWINS', 'MC-SMR-FOUND', 'MC-CLEAN-ENERGY', 'MC-CYBER-HYGIENE', 'MC-QUESTION-AI', 'MC-SYSTEMS']) order by 1 loop
    perform kafaa_cr_sync(x);
  end loop;
end $$;
